import{_ as e,o as a,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"Grading","description":"","frontmatter":{"title":"Grading"},"headers":[],"relativePath":"grading/intro.md","filePath":"grading/intro.md","lastUpdated":1789241305000}'),n={name:"grading/intro.md"};function o(d,t,s,l,c,m){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-label="Permalink to &quot;Grading&quot;">​</a></h1><p>Grading organizes a stone&#39;s weight, appearance, and report characteristics into comparable descriptions. Identification and disclosure support claims about identity, treatment, and authenticity. This module covers the GIA 4C diamond framework (Carat / Color / Clarity / Cut), the hue-tone-saturation model for coloured gems, and the disclosure norms for clarity types, treatments, and origin reports.</p><h2 id="grading-topics" tabindex="-1">Grading Topics <a class="header-anchor" href="#grading-topics" aria-label="Permalink to &quot;Grading Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Summary</th></tr></thead><tbody><tr><td><a href="./diamond-4cs.html">GIA 4Cs (Diamond)</a></td><td>A diamond-grading framework established by GIA in 1953 and widely adopted. Four independent measurements—carat, color, clarity, cut—jointly determine a polished diamond&#39;s market value.</td></tr><tr><td><a href="./colored-stones.html">Coloured-Stone Grading</a></td><td>Coloured gems lack a single 4C scheme. Instead, colour is graded on three axes—hue (position on the colour wheel), tone (lightness), and saturation (intensity). Many laboratories use these descriptive dimensions, but report terms and thresholds can differ.</td></tr><tr><td><a href="./clarity-types.html">Clarity Inclusion Types</a></td><td>The type, position, quantity, and visibility of inclusions and blemishes determine the clarity grade. The same feature matters differently in different gems—a &quot;jardin&quot; is normal in emerald but critical in diamond.</td></tr><tr><td><a href="./origin-disclosure.html">Origin &amp; Treatment Disclosure</a></td><td>Trade rules (CIBJO Blue Books; FTC Guides; AGTA Disclosure) require sellers to declare treatments and, when claimed, geographic origin. Common treatments are tier-ranked by their impact on value.</td></tr></tbody></table>',4)])])}const p=e(n,[["render",o]]);export{u as __pageData,p as default};
